+fn with_passes(passes: ThreadPasses) -> OpParams {
+    let mut p = thread(R_M8, None, ThreadHand::Right, true);
+    if let OpParams::Thread { passes: q, .. } = &mut p {
+        *q = passes;
+    }
+    p
+}
