+    assert!(msg.contains("leaves nothing to rough"), "{msg}");
+    let msg = refusal(&world, with_passes(ThreadPasses { finish: -0.05, ..ThreadPasses::default() }));
+    assert!(msg.contains("finishing pass depth cannot be negative"), "{msg}");
